    final small = medianWrapMs(build(baseCells), 80, elapsedUs: elapsedUs);
    final doubled = medianWrapMs(
      build(baseCells * 2),
      80,
      elapsedUs: elapsedUs,
    );
    final ratio = doubled / small;
    if (ratio < minRatio) minRatio = ratio;
    if (ratio > maxRatio) maxRatio = ratio;
